<template>
  <section class="report-layout">
    <div class="panel report-main">
      <div class="report-head"><div><h2>報表生成與歸檔</h2><p>報表直接讀取 CCPS 已確認資料，SQL Account 是否完成匯入不影響統計。</p></div><div class="format-badges"><span>PDF</span><span>XLSX</span></div></div>
      <div class="definition-strip"><button v-for="definition in definitions" :key="definition.id" :class="{ active: selectedType === definition.reportType }" @click="selectedType = definition.reportType"><b>{{ typeIcon(definition.reportType) }}</b><span>{{ definition.name }}</span><small>{{ definition.defaultFormat }}</small></button></div>
      <div v-if="loading" class="report-state">正在載入報表資料…</div><div v-else-if="errorMessage" class="report-state error"><strong>報表資料載入失敗</strong><span>{{ errorMessage }}</span><button @click="loadData">重試</button></div>
      <div v-else class="table-wrap report-table"><table><thead><tr><th>報表名稱</th><th>資料範圍</th><th>建案</th><th>格式</th><th>記錄數</th><th>狀態</th><th>建立人</th><th>完成時間</th><th>操作</th></tr></thead><tbody>
        <tr v-for="run in filteredRuns" :key="run.id"><td><strong>{{ run.reportName }}</strong><small>#{{ run.id }}</small></td><td>{{ run.dateStart }} ~ {{ run.dateEnd }}</td><td>{{ run.projectName || '全部建案' }}</td><td><span class="format-chip">{{ run.outputFormat }}</span></td><td>{{ run.recordCount ?? '—' }}</td><td><span class="report-tag" :class="run.status">{{ statusLabel(run.status) }}</span></td><td>{{ run.requestedByName || '系統' }}</td><td>{{ dateTime(run.completedAt) }}</td><td><button v-if="run.downloadable" class="download-button" @click="download(run)">下載</button><span v-else-if="run.errorMessage" class="error-hint" :title="run.errorMessage">查看錯誤</span><span v-else>—</span></td></tr>
        <tr v-if="!filteredRuns.length"><td colspan="9" class="empty-cell">尚無符合條件的報表記錄</td></tr>
      </tbody></table></div>
    </div>
    <aside class="panel report-detail"><template v-if="selectedDefinition"><div class="detail-title"><div class="report-icon">{{ typeIcon(selectedDefinition.reportType) }}</div><div><h3>{{ selectedDefinition.name }}</h3><p>{{ selectedDefinition.reportCode }}</p></div><span class="report-tag completed">已啟用</span></div><button class="generate-button" @click="openDialog(selectedDefinition)">產生此報表</button>
      <section class="detail-section"><h4>報表設定</h4><dl><div><dt>報表類型</dt><dd>{{ typeLabel(selectedDefinition.reportType) }}</dd></div><div><dt>預設格式</dt><dd>{{ selectedDefinition.defaultFormat }}</dd></div><div><dt>排程</dt><dd>{{ selectedDefinition.scheduleCron || '尚未設定' }}</dd></div><div><dt>最近更新</dt><dd>{{ dateTime(selectedDefinition.updatedAt) }}</dd></div></dl></section>
      <section class="detail-section"><h4>資料口徑</h4><p>{{ definitionHint(selectedDefinition.reportType) }}</p></section><section class="detail-section"><h4>最近產生</h4><article v-for="run in typeRuns.slice(0,5)" :key="run.id" class="recent-run"><div><strong>{{ run.dateStart }} ~ {{ run.dateEnd }}</strong><small>{{ run.recordCount ?? 0 }} 筆 · {{ run.outputFormat }}</small></div><span class="report-tag" :class="run.status">{{ statusLabel(run.status) }}</span></article><p v-if="!typeRuns.length">尚無記錄</p></section>
    </template></aside>
    <dialog ref="reportDialog" class="report-dialog"><form @submit.prevent="generate"><header><div><h3>產生報表</h3><p>生成完成後會保存歷史記錄並提供下載。</p></div><button type="button" @click="closeDialog">×</button></header><div class="dialog-body"><label>報表類型<select v-model="form.reportType" @change="syncDefaultFormat"><option v-for="definition in definitions" :key="definition.id" :value="definition.reportType">{{ definition.name }}</option></select></label><div class="form-grid"><label>開始日期<input v-model="form.dateStart" type="date" required></label><label>結束日期<input v-model="form.dateEnd" type="date" required></label></div><label>建案範圍<select v-model="form.projectId"><option :value="null">全部建案</option><option v-for="project in projects" :key="project.id" :value="project.id">{{ project.name }}</option></select></label><fieldset><legend>輸出格式</legend><label><input v-model="form.outputFormat" type="radio" value="XLSX"><span><b>XLSX</b><small>適合篩選、計算及會計複核</small></span></label><label><input v-model="form.outputFormat" type="radio" value="PDF"><span><b>PDF</b><small>適合列印、簽核及歸檔</small></span></label></fieldset><p v-if="dialogError" class="dialog-error">{{ dialogError }}</p></div><menu><button type="button" @click="closeDialog">取消</button><button class="save-button" :disabled="generating">{{ generating ? '產生中…' : '產生報表' }}</button></menu></form></dialog>
  </section>
</template>
<script>
import { downloadAdminReport, fetchAdminReports, generateAdminReport } from '../services/propertyApi';
const monthRange=()=>{const d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),last=new Date(y,d.getMonth()+1,0).getDate();return[`${y}-${m}-01`,`${y}-${m}-${last}`];};
export default { inject:['page'],data(){const[start,end]=monthRange();return{loading:true,errorMessage:'',definitions:[],runs:[],projects:[],selectedType:'property_payment',form:{reportType:'property_payment',dateStart:start,dateEnd:end,projectId:null,outputFormat:'XLSX'},generating:false,dialogError:''};},
computed:{selectedDefinition(){return this.definitions.find(d=>d.reportType===this.selectedType)||this.definitions[0]||null;},typeRuns(){return this.runs.filter(r=>r.definitionId===this.selectedDefinition?.id);},keyword(){return String(this.page.globalSearch||this.page.moduleSearch||'').trim().toLowerCase();},filteredRuns(){const status=this.page.statusFilter,project=this.page.projectFilter;return this.runs.filter(r=>(!this.keyword||`${r.reportName} ${r.requestedByName||''} ${r.projectName||''}`.toLowerCase().includes(this.keyword))&&(!project||project.includes('全部')||r.projectName===project)&&(!status||status.includes('全部')||(status==='已完成'&&r.status==='completed')||(status==='產生中'&&['queued','processing'].includes(r.status))||(status==='產生失敗'&&r.status==='failed')));},createNonce(){return this.page.adminReportCreateNonce;},refreshNonce(){return this.page.adminReportRefreshNonce;}},
watch:{createNonce(v,p){if(v>p)this.openDialog(this.selectedDefinition);},refreshNonce(v,p){if(v>p)this.loadData();}},mounted(){this.page.projectFilter='全部建案';this.page.statusFilter='全部狀態';this.loadData();},methods:{async loadData(){this.loading=true;this.errorMessage='';try{const r=await fetchAdminReports();this.definitions=r.definitions||[];this.runs=r.runs||[];this.projects=r.projects||[];this.page.adminReportProjects=this.projects.map(p=>p.name);if(!this.definitions.some(d=>d.reportType===this.selectedType))this.selectedType=this.definitions[0]?.reportType||'';this.setMetrics(r.summary||{});this.setExport();}catch(e){this.errorMessage=e.message||'報表資料載入失敗';this.page.adminReportMetrics=null;}finally{this.loading=false;}},setMetrics(s){this.page.adminReportMetrics=[{label:'可用報表',value:`${Number(s.definitionCount||0)} 種`,delta:'資料庫報表定義',trend:'up'},{label:'本月產生',value:`${Number(s.generatedThisMonth||0)} 份`,delta:'PDF 與 XLSX',trend:'up'},{label:'已完成',value:`${Number(s.completedCount||0)} 份`,delta:'可下載歸檔',trend:'up'},{label:'產生失敗',value:`${Number(s.failedCount||0)} 份`,delta:'保留錯誤原因',trend:Number(s.failedCount)?'down':'up'}];},setExport(){this.page.adminReportExportHeaders=['報表名稱','開始日期','結束日期','建案','格式','記錄數','狀態','建立人','完成時間','錯誤'];this.page.adminReportExportRows=this.runs.map(r=>[r.reportName,r.dateStart,r.dateEnd,r.projectName||'全部建案',r.outputFormat,r.recordCount??'',this.statusLabel(r.status),r.requestedByName||'',this.dateTime(r.completedAt),r.errorMessage||'']);},openDialog(definition){const[start,end]=monthRange();const d=definition||this.selectedDefinition;this.form={reportType:d?.reportType||'property_payment',dateStart:start,dateEnd:end,projectId:null,outputFormat:d?.defaultFormat||'XLSX'};this.dialogError='';this.$refs.reportDialog?.showModal();},closeDialog(){if(!this.generating)this.$refs.reportDialog?.close();},syncDefaultFormat(){const d=this.definitions.find(x=>x.reportType===this.form.reportType);if(d)this.form.outputFormat=d.defaultFormat;},async generate(){this.generating=true;this.dialogError='';try{const run=await generateAdminReport(this.form);if(run.status==='failed'){this.dialogError=run.errorMessage||'報表產生失敗';return;}this.$refs.reportDialog?.close();this.selectedType=this.form.reportType;await this.loadData();this.page.showToast(`報表已完成，共 ${Number(run.recordCount||0)} 筆`);}catch(e){this.dialogError=e.message||'報表產生失敗';}finally{this.generating=false;}},async download(run){try{const f=await downloadAdminReport(run.id);const u=URL.createObjectURL(f.blob),a=document.createElement('a');a.href=u;a.download=`${run.reportName}.${run.outputFormat.toLowerCase()}`;a.click();URL.revokeObjectURL(u);}catch(e){this.page.showToast(e.message||'下載失敗');}},typeIcon(v){return({property_payment:'款',rent_collection:'租',income_expense:'收',maintenance:'修',reserve:'金',finance:'財',sync:'同'})[v]||'表';},typeLabel(v){return({property_payment:'房款',rent_collection:'租金',income_expense:'收支',maintenance:'維修',reserve:'預備金',finance:'財務',sync:'同步'})[v]||v;},definitionHint(v){return({property_payment:'按交易日期統計房款財務記錄、付款狀態及同步狀態。',rent_collection:'按交易日期統計已登記的租金收款及相關租客、單位。',income_expense:'匯總已確認的財務交易，供月度收支複核。',maintenance:'按報修日期列出工單、供應商、預估或實際費用及完成狀態。',reserve:'按預備金異動日期列出充值、扣款、業主單位及異動後餘額。',finance:'列出日期範圍內全部財務記錄及確認、付款、同步狀態。',sync:'按批次建立日期統計 SQL Account 匯出成功、失敗及總筆數。'})[v]||'依 CCPS 資料庫產生。';},statusLabel(v){return({completed:'已完成',failed:'失敗',processing:'產生中',queued:'排隊中'})[v]||v;},dateTime(v){return v?String(v).replace('T',' ').slice(0,16):'—';}}};
</script>
<style scoped>
