ff;font-size:20px;font-weight:700}.detail-title h3{margin:0 0 4px;font-size:16px}.detail-title p{margin:0;color:#718096;font-size:11px}.generate-button{width:100%;margin:15px 0;border:0;border-radius:7px;background:#cf8900;color:#fff;padding:10px}.detail-section{padding:14px 0;border-top:1px solid #e2e8ef}.detail-section h4{margin:0 0 11px}.detail-section dl{margin:0}.detail-section dl div{display:flex;justify-content:space-between;gap:10px;padding:5px 0}.detail-section dt{color:#718096}.detail-section dd{margin:0;text-align:right;font-weight:600}.detail-section p{color:#65758a;font-size:12px;line-height:1.65}.recent-run{display:flex;justify-content:space-between;gap:7px;padding:8px 0;border-bottom:1px dashed #dfe6ed}.recent-run strong,.recent-run small{display:block}.recent-run small{margin-top:3px;color:#718096;font-size:10px}.report-state{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;min-height:280px;color:#718096}.report-state.error strong,.dialog-error{color:#c5313b}.report-dialog{width:min(590px,calc(100vw - 32px));padding:0;border:0;border-radius:12px;box-shadow:0 22px 70px #10233b42}.report-dialog::backdrop{background:#0a172a80}.report-dialog form{margin:0}.report-dialog header{display:flex;justify-content:space-between;padding:20px 22px;border-bottom:1px solid #e1e7ee}.report-dialog h3{margin:0 0 5px}.report-dialog header p{margin:0;color:#718096;font-size:12px}.report-dialog header button{border:0;background:transparent;font-size:26px}.dialog-body{display:grid;gap:14px;padding:20px 22px}.dialog-body>label,.form-grid label{display:grid;gap:6px;font-weight:600}.dialog-body select,.dialog-body input[type=date]{border:1px solid #ccd7e3;border-radius:7px;padding:10px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.dialog-body fieldset{display:grid;grid-template-columns:1fr 1fr;gap:8px;border:1px solid #dce4ed;border-radius:8px;padding:12px}.dialog-body fieldset label{display:grid;grid-template-columns:auto 1fr;gap:8px;padding:8px}.dialog-body fieldset b,.dialog-body fieldset small{display:block}.dialog-body fieldset small{margin-top:3px;color:#718096;font-size:10px}.report-dialog menu{display:flex;justify-content:flex-end;gap:8px;margin:0;padding:14px 22px;background:#f6f8fb}.report-dialog menu button{border:1px solid #ccd7e3;border-radius:7px;background:#fff;padding:9px 16px}.report-dialog menu .save-button{background:#cf8900;border-color:#cf8900;color:#fff}.report-dialog menu button:disabled{opacity:.5}@media(max-width:1200px){.report-layout{grid-template-columns:1fr}}@media(max-width:600px){.form-grid,.dialog-body fieldset{grid-template-columns:1fr}}
</style>
